'use client';

import {
  useEffect, useId, useImperativeHandle, useLayoutEffect, useRef, useState, useSyncExternalStore,
  type CSSProperties, type KeyboardEvent, type ReactNode, type Ref,
} from 'react';
import { motion } from 'motion/react';
import './otp-input.css';

export type OtpStatus = 'idle' | 'verifying' | 'error' | 'success';
export type OtpInputVariant = 'clean' | 'classic';
export type OtpInputHandle = {
  focus: (index?: number) => void;
  clear: () => void;
};

export type OtpInputProps = {
  length?: number;
  separator?: boolean | number;
  numeric?: boolean;
  value?: string;
  defaultValue?: string;
  onChange?: (code: string) => void;
  onComplete?: (code: string) => void;
  status?: OtpStatus;
  errorMessage?: ReactNode;
  clearOnError?: boolean;
  successLabel?: string;
  onResend?: () => void;
  resendIn?: number;
  align?: 'start' | 'center';
  disabled?: boolean;
  autoFocus?: boolean;
  label?: string;
  className?: string;
  variant?: OtpInputVariant;
  theme?: 'light' | 'dark';
  reduceMotion?: boolean;
  id?: string;
  name?: string;
  form?: string;
  required?: boolean;
  ref?: Ref<OtpInputHandle>;
};

const ease = [.22, 1, .36, 1] as const;
const sanitize = (text: string, numeric: boolean, length: number) =>
  text.toUpperCase().replace(numeric ? /[^0-9]/g : /[^A-Z0-9]/g, '').slice(0, length);

const reducedMotionQuery = '(prefers-reduced-motion: reduce)';
function subscribeReducedMotion(onChange: () => void) {
  const query = window.matchMedia(reducedMotionQuery);
  query.addEventListener('change', onChange);
  return () => query.removeEventListener('change', onChange);
}
const getReducedMotion = () => window.matchMedia(reducedMotionQuery).matches;
const getServerReducedMotion = () => false;

/** One native input owns the value; the slots are a presentation of that input. */
export function OtpInput({
  length = 6, separator = false, numeric = true, value, defaultValue = '', onChange,
  onComplete, status = 'idle', errorMessage = "That code didn't work. Try again.",
  clearOnError = true, successLabel = 'Verified', onResend, resendIn = 30,
  align = 'start', disabled = false, autoFocus = false, label = 'Verification code',
  className = '', variant = 'clean', theme, reduceMotion = false,
  id, name, form, required, ref,
}: OtpInputProps) {
  const count = Math.max(1, Math.floor(length));
  const clean = (text: string) => sanitize(text, numeric, count);
  const [internalValue, setInternalValue] = useState(() => clean(defaultValue));
  const code = clean(value ?? internalValue);
  const [active, setActive] = useState(Math.min(code.length, count - 1));
  const [focused, setFocused] = useState(false);
  const [dismissedError, setDismissedError] = useState(false);
  const [clearing, setClearing] = useState(false);
  const [bulkFill, setBulkFill] = useState(false);
  const [remaining, setRemaining] = useState(Math.max(0, Math.ceil(resendIn)));
  const [announcement, setAnnouncement] = useState('');
  const [resendCycle, setResendCycle] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const slotsRef = useRef<HTMLDivElement>(null);
  const pillContentRef = useRef<HTMLSpanElement>(null);
  const errorTimers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const selection = useRef<{ start: number; end: number } | null>(null);
  const edited = useRef(false);
  const currentCode = useRef(code);
  const latest = useRef({ onChange, onComplete, controlled: value !== undefined });
  const [geometry, setGeometry] = useState({
    width: 0, height: 0, pillWidth: 0, gap: 0, boxes: [] as { x: number; width: number }[],
  });
  const systemReduced = useSyncExternalStore(subscribeReducedMotion, getReducedMotion, getServerReducedMotion);
  const instant = reduceMotion || systemReduced;
  const messageId = `${useId()}-error`;
  const locked = disabled || status === 'verifying' || status === 'success';
  const showError = status === 'error' && !dismissedError;
  const visualStatus = status === 'error' && dismissedError ? 'idle' : status;
  const split = separator === true ? Math.floor(count / 2) : Number(separator);
  const hasSeparator = split > 0 && split < count;

  useLayoutEffect(() => {
    currentCode.current = code;
    latest.current = { onChange, onComplete, controlled: value !== undefined };
  });

  function cancelErrorClear() {
    errorTimers.current.forEach(clearTimeout);
    errorTimers.current = [];
    setClearing(false);
  }

  function moveTo(index: number, nextCode = currentCode.current, focus = false) {
    const next = Math.max(0, Math.min(index, nextCode.length, count - 1));
    if (focus) inputRef.current?.focus({ preventScroll: true });
    setActive(next);
    selection.current = { start: next, end: Math.min(next + 1, nextCode.length) };
    // Also apply when a key moves to the already-active box (no React render).
    inputRef.current?.setSelectionRange(selection.current.start, selection.current.end);
  }

  function publish(next: string, userEdit: boolean, bulk = false) {
    const normalized = clean(next);
    if (userEdit) {
      cancelErrorClear();
      edited.current = true;
      setDismissedError(true);
      setBulkFill(bulk);
    }
    if (normalized === currentCode.current) return;
    currentCode.current = normalized;
    if (!latest.current.controlled) setInternalValue(normalized);
    latest.current.onChange?.(normalized);
    if (userEdit && normalized.length === count) latest.current.onComplete?.(normalized);
  }

  useImperativeHandle(ref, () => ({
    focus(index) {
      if (!locked) moveTo(index ?? Math.min(code.length, count - 1), code, true);
    },
    clear() {
      cancelErrorClear();
      publish('', false);
      moveTo(0, '');
    },
  }));

  useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input || !focused) return;
    const next = Math.min(active, code.length, count - 1);
    if (next !== active) setActive(next);
    const range = selection.current ?? { start: next, end: Math.min(next + 1, code.length) };
    input.setSelectionRange(Math.min(range.start, code.length), Math.min(range.end, code.length));
    selection.current = null;
  }, [code, active, focused, count]);

  useEffect(() => {
    if (autoFocus && !locked) inputRef.current?.focus({ preventScroll: true });
    // autoFocus is a mount-time option; status changes must not steal focus.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useLayoutEffect(() => {
    const slots = slotsRef.current;
    const pill = pillContentRef.current;
    if (!slots || !pill) return;
    const measure = () => {
      const boxes = [...slots.querySelectorAll<HTMLElement>('[data-otp-slot]')]
        .map(box => ({ x: box.offsetLeft, width: parseFloat(getComputedStyle(box).width) }));
      const next = { width: slots.getBoundingClientRect().width,
        height: slots.getBoundingClientRect().height, gap: parseFloat(getComputedStyle(slots).columnGap) || 0, pillWidth: pill.getBoundingClientRect().width, boxes };
      setGeometry(old => old.width === next.width && old.height === next.height &&
        old.pillWidth === next.pillWidth && old.boxes.length === boxes.length &&
        old.boxes.every((box, index) => box.x === boxes[index].x && box.width === boxes[index].width)
        ? old : next);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(slots);
    observer.observe(pill);
    return () => observer.disconnect();
  }, [count, split, variant, successLabel]);

  useEffect(() => {
    cancelErrorClear();
    setDismissedError(false);
    if (status !== 'error' || !clearOnError || disabled) return;
    const rejectedCode = currentCode.current;
    errorTimers.current = [
      setTimeout(() => setClearing(true), instant ? 0 : 700),
      setTimeout(() => {
        if (currentCode.current === rejectedCode) {
          publish('', false);
          moveTo(0, '');
        }
        setClearing(false);
      }, instant ? 0 : 900),
    ];
    return () => errorTimers.current.forEach(clearTimeout);
    // Callbacks are read through latest so parent renders don't restart the shake/clear.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, clearOnError, disabled, instant]);

  useEffect(() => {
    if (!onResend || status === 'success') return;
    const deadline = Date.now() + Math.max(0, resendIn) * 1000;
    const tick = () => {
      const seconds = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
      setRemaining(seconds);
      if (!seconds) {
        setAnnouncement('You can resend the code now');
        clearInterval(timer);
      }
    };
    setRemaining(Math.max(0, Math.ceil(resendIn)));
    const timer = setInterval(tick, 250);
    if (resendIn <= 0) tick();
    return () => clearInterval(timer);
  }, [Boolean(onResend), resendIn, resendCycle, status === 'success']);

  const selectionRange = () => ({
    start: inputRef.current?.selectionStart ?? active,
    end: inputRef.current?.selectionEnd ?? active,
  });

  function insert(text: string, wholeCode = false) {
    const incoming = clean(text);
    if (!incoming) return;
    const { start, end } = selectionRange();
    const replaceAll = wholeCode || incoming.length === count;
    const at = replaceAll ? 0 : Math.min(start, code.length, count - 1);
    const next = replaceAll ? incoming : clean(code.slice(0, at) + incoming +
      code.slice(Math.max(end, at + incoming.length)));
    publish(next, true, incoming.length > 1);
    moveTo(at + incoming.length, next);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (locked || event.nativeEvent.isComposing) return;
    if (event.metaKey || event.ctrlKey || event.altKey) return;
    if (event.shiftKey && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    const { start, end } = selectionRange();
    if (['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) {
      event.preventDefault();
      moveTo(event.key === 'Home' ? 0 : event.key === 'End' ? code.length :
        active + (event.key === 'ArrowLeft' ? -1 : 1));
    } else if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault();
      const at = end - start > 1 ? start : event.key === 'Backspace' && active >= code.length
        ? Math.max(0, code.length - 1) : active;
      const next = code.slice(0, at) + code.slice(end - start > 1 ? end : at + 1);
      publish(next, true);
      moveTo(event.key === 'Backspace' ? end - start > 1 ? start : active - 1 : at, next);
    } else if (event.key.length === 1) {
      event.preventDefault();
      insert(event.key);
    }
  }

  const columns = Array.from({ length: count }, (_, index) =>
    `${hasSeparator && index === split ? '8px ' : ''}minmax(0, 1fr)`).join(' ');
  const ring = geometry.boxes[Math.min(active, count - 1)];
  const success = status === 'success';
  const liveMessage = status === 'verifying' ? 'Verifying code' : success ? successLabel
    : showError ? errorMessage : announcement;

  return (
    <div className={`rui-otp rui-otp--${variant} ${className}`} data-theme={theme}
      data-state={visualStatus} data-align={align} data-disabled={disabled || undefined}
      data-reduced-motion={instant || undefined} data-clearing={clearing || undefined}
      style={{ '--otp-count': count, '--otp-gap-count': count - 1 + Number(hasSeparator),
        '--otp-separator-width': hasSeparator ? '8px' : '0px' } as CSSProperties}>
      <motion.div className="rui-otp__field" initial={false}
        animate={{ x: showError && !instant ? [0, -4, 4, -3, 2, 0] : 0 }}
        transition={{ duration: instant ? 0 : .38 }}>
        <div ref={slotsRef} className="rui-otp__slots" style={{ gridTemplateColumns: columns }} aria-hidden="true">
          {Array.from({ length: count }, (_, index) => [
            hasSeparator && index === split && <span key={`sep-${index}`} className="rui-otp__separator" />,
            <motion.span key={index} data-otp-slot={index} data-filled={Boolean(code[index]) || undefined}
              className="rui-otp__box" style={{ '--otp-shimmer-delay': `${index * .05}s` } as CSSProperties} initial={false}
              animate={{ x: success && geometry.boxes[index]
                ? ((count - 1) / 2 - index) * (geometry.boxes[index].width + geometry.gap) : 0,
              scale: success ? .7 : 1, opacity: success ? 0 : 1 }}
              transition={{ duration: instant ? 0 : .38, ease,
                opacity: { duration: instant ? 0 : .26, delay: success && !instant ? .1 : 0, ease: [.25, .1, .25, 1] } }}>
              <motion.span className="rui-otp__digit-fade" initial={false}
                animate={{ opacity: clearing ? 0 : 1 }} transition={{ duration: instant ? 0 : .2 }}>
                {code[index] && <motion.span key={code[index]} className="rui-otp__digit"
                  initial={edited.current && !instant ? { opacity: 0, y: 5, scale: .9, filter: 'blur(3px)' } : false}
                  animate={{ opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' }}
                  transition={{ duration: instant ? 0 : .24, ease, delay: bulkFill && !instant ? index * .035 : 0 }}>
                  {code[index]}
                </motion.span>}
              </motion.span>
            </motion.span>,
          ])}
          <motion.span className="rui-otp__ring" initial={false}
            animate={{ x: ring?.x ?? 0, width: ring?.width ?? 0, height: geometry.height,
              opacity: focused && !locked && ring ? 1 : 0 }}
            transition={{ duration: instant ? 0 : .26, ease, opacity: { duration: instant ? 0 : .18 } }}>
            {!code[active] && <span className="rui-otp__caret" />}
          </motion.span>
          <span className="rui-otp__pill-position">
            <motion.span className="rui-otp__pill" initial={false}
              animate={{ width: success ? Math.round(geometry.pillWidth) || 'max-content' : geometry.width,
                opacity: success ? 1 : 0 }}
              transition={{ width: { duration: instant ? 0 : .3, delay: success && !instant ? .24 : 0, ease },
                opacity: { duration: instant ? 0 : .16, delay: success && !instant ? .14 : 0, ease: [.25, .1, .25, 1] } }}>
              <motion.span ref={pillContentRef} className="rui-otp__pill-content" initial={false}
                animate={{ opacity: success ? 1 : 0 }}
                transition={{ duration: instant ? 0 : .16, delay: success && !instant ? .5 : 0 }}>
                <svg className="rui-otp__check" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <motion.path d="M5.5 12.5l4 4L18.5 8" initial={false} animate={{ pathLength: success ? 1 : 0 }}
                    transition={{ duration: instant ? 0 : .24, delay: success && !instant ? .5 : 0, ease }} />
                </svg>
                <span>{successLabel}</span>
              </motion.span>
            </motion.span>
          </span>
        </div>
        <input ref={inputRef} id={id} name={name} form={form} required={required}
          className="rui-otp__input" type="text" value={code}
          inputMode={numeric ? 'numeric' : 'text'} autoComplete="one-time-code"
          pattern={numeric ? `[0-9]{${count}}` : `[A-Za-z0-9]{${count}}`}
          autoCapitalize="characters" autoCorrect="off" spellCheck={false}
          aria-label={`${label}, ${count} ${numeric ? 'digits' : 'characters'}`}
          aria-invalid={showError || undefined} aria-describedby={showError ? messageId : undefined}
          aria-busy={status === 'verifying' || undefined} disabled={disabled} readOnly={locked}
          tabIndex={success ? -1 : 0}
          onFocus={() => { setFocused(true); moveTo(Math.min(code.length, count - 1)); }}
          onBlur={() => { setFocused(false); selection.current = null; }}
          onPointerDown={event => {
            if (locked) return;
            const slots = slotsRef.current;
            if (!slots) return;
            event.preventDefault();
            const x = event.clientX - slots.getBoundingClientRect().left;
            const nearest = geometry.boxes.reduce((best, box, index, boxes) =>
              Math.abs(x - box.x - box.width / 2) < Math.abs(x - boxes[best].x - boxes[best].width / 2) ? index : best, 0);
            moveTo(nearest, code, true);
          }}
          onKeyDown={handleKeyDown}
          onPaste={event => {
            event.preventDefault();
            if (!locked) insert(event.clipboardData.getData('text'));
          }}
          onCut={event => {
            if (locked) { event.preventDefault(); return; }
            const { start, end } = selectionRange();
            if (start === end) return;
            event.preventDefault();
            event.clipboardData.setData('text/plain', code.slice(start, end));
            const next = code.slice(0, start) + code.slice(end);
            publish(next, true);
            moveTo(start, next);
          }}
          onChange={event => {
            if (locked) return;
            const raw = event.currentTarget.value;
            const cursor = clean(raw.slice(0, event.currentTarget.selectionStart ?? raw.length)).length;
            const next = clean(raw);
            publish(next, true, Math.abs(next.length - code.length) > 1);
            moveTo((event.nativeEvent as InputEvent).inputType === 'deleteContentBackward' ? active - 1 : cursor, next);
          }} />
      </motion.div>
      <div className="rui-otp__message" data-visible={showError || undefined}>
        <div className="rui-otp__message-clip">
          <p id={messageId} className="rui-otp__message-text" aria-hidden={!showError}>
            <svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.5">
              <path d="M12 8v4.5M12 16h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z" />
            </svg>
            <span>{errorMessage}</span>
          </p>
        </div>
      </div>
      {onResend && <div className="rui-otp__resend" aria-hidden={success || undefined}>
        <span>Didn't get a code?</span>
        {remaining > 0 ? <span className="rui-otp__wait" key="countdown">Resend in{' '}
          <span className="rui-otp__time">{Math.floor(remaining / 60)}:{String(remaining % 60).padStart(2, '0')}</span>
        </span> : <button className="rui-otp__resend-button" key="resend" type="button"
          disabled={locked} tabIndex={success ? -1 : 0} onClick={() => {
            cancelErrorClear();
            publish('', false);
            setDismissedError(true);
            setRemaining(Math.max(0, Math.ceil(resendIn)));
            setResendCycle(cycle => cycle + 1);
            setAnnouncement('Code resent');
            onResend();
            moveTo(0, '', true);
          }}>Resend code</button>}
      </div>}
      <span className="rui-otp__live" role="status" aria-live="polite" aria-atomic="true">{liveMessage}</span>
    </div>
  );
}

.rui-otp {
  --otp-ink: rgb(0 0 0 / .88);
  --otp-muted: rgb(0 0 0 / .61);
  --otp-faint: rgb(0 0 0 / .45);
  --otp-surface: #fff;
  --otp-filled: #f7f7f7;
  --otp-line: rgb(0 0 0 / .06);
  --otp-shadow: 0 0 0 .5px var(--otp-line), 0 1px 1px -1px rgb(0 0 0 / .1), 0 1px 2px rgb(0 0 0 / .05);
  --otp-ring: 0 0 0 .5px rgb(0 96 226 / .765), 0 0 0 2px rgb(0 96 226 / .35);
  --otp-focus: rgb(0 96 226 / .765);
  --otp-separator: rgb(0 0 0 / .27);
  --otp-error: #e5484d;
  --otp-error-fill: rgb(229 72 77 / .08);
  --otp-success-fill: rgb(26 154 82 / .08);
  --otp-success-ink: #1a9a52;
  --otp-box-width: 40px;
  --otp-radius: 8px;
  --otp-gap: 8px;
  --otp-field-padding: 3px;
  container-type: inline-size;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  min-width: 0;
  color: var(--otp-ink);
  font-family: inherit;
  font-size: 13px;
  line-height: 20px;
  text-align: left;
  -webkit-tap-highlight-color: transparent;
}
.rui-otp *, .rui-otp *::before, .rui-otp *::after { box-sizing: border-box; }
.rui-otp--classic {
  --otp-ink: #171717;
  --otp-muted: #404040;
  --otp-faint: #8f8f8f;
  --otp-surface: #fafafa;
  --otp-filled: #fff;
  --otp-filled-line: #cfcfd4;
  --otp-success-ink: #2f9e5b;
  --otp-line: #e4e4e7;
  --otp-shadow: inset 0 0 0 1px var(--otp-line);
  --otp-ring: inset 0 0 0 1.5px #171717, 0 0 0 4px rgb(23 23 23 / .07);
  --otp-focus: #171717;
  --otp-separator: #c4c4c8;
  --otp-box-width: 48px;
  --otp-radius: 11.52px;
  --otp-gap: 6px;
  --otp-field-padding: 0px;
  font-size: 13.5px;
  line-height: 19.575px;
}
:where(.dark, [data-theme="dark"]) .rui-otp:not([data-theme="light"]), .rui-otp[data-theme="dark"] {
  --otp-ink: rgb(255 255 255 / .9);
  --otp-muted: rgb(255 255 255 / .62);
  --otp-faint: rgb(255 255 255 / .46);
  --otp-surface: #1c1c1e;
  --otp-filled: #252527;
  --otp-line: rgb(255 255 255 / .1);
  --otp-shadow: 0 0 0 .5px var(--otp-line), 0 1px 2px rgb(0 0 0 / .4);
  --otp-ring: 0 0 0 .5px #4d8dff, 0 0 0 2px rgb(77 141 255 / .5);
  --otp-focus: #4d8dff;
  --otp-separator: rgb(255 255 255 / .3);
  --otp-error: #ff6369;
  --otp-error-fill: rgb(255 99 105 / .14);
  --otp-success-fill: rgb(62 194 122 / .14);
  --otp-success-ink: #3ec27a;
}
:where(.dark, [data-theme="dark"]) .rui-otp--classic:not([data-theme="light"]), .rui-otp--classic[data-theme="dark"] {
  --otp-ink: #ededed;
  --otp-muted: #c8c8cc;
  --otp-faint: #8b8b92;
  --otp-surface: #1d1d20;
  --otp-filled: #19191b;
  --otp-filled-line: #3a3a40;
  --otp-success-ink: #4cc38a;
  --otp-line: #2a2a2e;
  --otp-shadow: inset 0 0 0 1px var(--otp-line);
  --otp-ring: inset 0 0 0 1.5px #ededed, 0 0 0 4px rgb(255 255 255 / .08);
  --otp-focus: #ededed;
  --otp-separator: #4a4a50;
}
.rui-otp[data-align="center"] { align-items: center; text-align: center; }
.rui-otp[data-disabled] { opacity: .45; }
.rui-otp__field {
  position: relative;
  width: calc(var(--otp-box-width) * var(--otp-count) + var(--otp-gap) * var(--otp-gap-count) + var(--otp-separator-width));
  max-width: 100%;
  padding-block: var(--otp-field-padding);
  flex: none;
}
.rui-otp__slots { position: relative; display: grid; align-items: center; gap: var(--otp-gap); width: 100%; }
.rui-otp__box {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  height: 44px;
  overflow: hidden;
  border-radius: var(--otp-radius);
  background: var(--otp-surface);
  color: var(--otp-ink);
  box-shadow: var(--otp-shadow);
  font-size: 15px;
  font-weight: 500;
  line-height: 24px;
  user-select: none;
  transition: box-shadow .22s, background-color .22s, color .22s;
}
.rui-otp--classic .rui-otp__box {
  height: auto;
  aspect-ratio: 1 / 1.18;
  font-size: min(22.08px, 6.42cqi);
  line-height: 1.45;
}
.rui-otp--classic .rui-otp__box[data-filled] { background: var(--otp-filled); box-shadow: inset 0 0 0 1px var(--otp-filled-line); }
.rui-otp--clean .rui-otp__box[data-filled] { background: var(--otp-filled); box-shadow: none; }
.rui-otp__digit-fade, .rui-otp__digit { display: inline-block; }
.rui-otp__separator { width: 8px; height: 1px; border-radius: 1px; background: var(--otp-separator); transition: opacity .2s; }
.rui-otp--classic .rui-otp__separator { height: 2px; }
.rui-otp__ring {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--otp-radius);
  box-shadow: var(--otp-ring);
  pointer-events: none;
  z-index: 2;
}
.rui-otp__caret { width: 1px; height: 18px; border-radius: 1px; background: var(--otp-focus); animation: rui-otp-blink 1.1s ease-in-out infinite; }
.rui-otp--classic .rui-otp__caret { width: 1.5px; height: 40%; }
.rui-otp .rui-otp__input {
  appearance: none;
  position: absolute;
  inset: var(--otp-field-padding) 0;
  width: 100%;
  height: calc(100% - var(--otp-field-padding) * 2);
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  outline: none;
  box-shadow: none;
  background: transparent;
  color: transparent;
  -webkit-text-fill-color: transparent;
  caret-color: transparent;
  font-family: inherit;
  font-size: 16px;
  font-weight: 400;
  line-height: 20px;
  cursor: text;
  z-index: 3;
}
.rui-otp__input::selection { color: transparent; background: transparent; }
.rui-otp__input:read-only { cursor: default; }
.rui-otp__input:disabled { cursor: not-allowed; }
.rui-otp__pill-position { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; pointer-events: none; }
.rui-otp__pill {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
  max-width: 100%;
  border-radius: var(--otp-radius);
  background: var(--otp-surface);
  box-shadow: var(--otp-shadow);
  overflow: hidden;
  transition: background-color .3s .36s;
}
.rui-otp__pill-content { display: flex; align-items: center; flex: none; width: max-content; gap: 6px; padding: 0 14px 0 12px; color: var(--otp-ink); font-size: 13px; font-weight: 500; line-height: 20px; white-space: nowrap; }
.rui-otp__check { flex: none; width: 16px; height: 16px; color: var(--otp-success-ink); }
.rui-otp--classic .rui-otp__pill-content { font-size: 14px; padding-right: 15px; }
.rui-otp--classic .rui-otp__check { width: 17px; height: 17px; }
.rui-otp__message { display: grid; grid-template-rows: 0fr; width: 100%; transition: grid-template-rows .3s cubic-bezier(.22, 1, .36, 1); }
.rui-otp__message[data-visible] { grid-template-rows: 1fr; }
.rui-otp__message-clip { min-height: 0; overflow: hidden; }
.rui-otp__message-text { display: flex; align-items: center; justify-content: flex-start; gap: 6px; margin: 0; padding: 8px 0 0; color: var(--otp-muted); font-size: 12px; line-height: 16px; opacity: 0; transform: translateY(-4px); transition: opacity .2s, transform .3s cubic-bezier(.22, 1, .36, 1); }
.rui-otp[data-align="center"] .rui-otp__message-text { justify-content: center; }
.rui-otp__message[data-visible] .rui-otp__message-text { opacity: 1; transform: none; transition-delay: .06s; }
.rui-otp__message-text svg { width: 14px; height: 14px; flex: none; color: var(--otp-error); }
.rui-otp--classic .rui-otp__message-text { padding-top: 10px; font-size: 13px; line-height: 18.85px; }
.rui-otp--classic .rui-otp__message-text svg { width: 15px; height: 15px; }
.rui-otp__resend { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; min-height: 28px; margin-top: 12px; color: var(--otp-faint); font-size: 12px; line-height: 16px; transition: opacity .22s; }
.rui-otp[data-align="center"] .rui-otp__resend { justify-content: center; }
.rui-otp--classic .rui-otp__resend { min-height: 18.85px; gap: 4px; margin-top: 14px; font-size: 13px; line-height: 18.85px; }
.rui-otp__wait { color: var(--otp-muted); animation: rui-otp-enter .26s cubic-bezier(.22, 1, .36, 1) both; }
.rui-otp__time { font-variant-numeric: tabular-nums; color: var(--otp-ink); }
.rui-otp .rui-otp__resend-button { appearance: none; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: 6px; background: transparent; color: var(--otp-muted); box-shadow: inset 0 0 0 .5px var(--otp-line); margin: 0; padding: 4px 10px; font-family: inherit; font-size: 13px; font-weight: 500; line-height: 20px; cursor: pointer; animation: rui-otp-enter .26s cubic-bezier(.22, 1, .36, 1) both; transition: background-color .16s, color .16s; }
.rui-otp .rui-otp__resend-button:hover:not(:disabled) { background: var(--otp-filled); color: var(--otp-ink); }
.rui-otp .rui-otp__resend-button:focus-visible { outline: 2px solid var(--otp-focus); outline-offset: 3px; }
.rui-otp .rui-otp__resend-button:disabled { opacity: .5; cursor: default; }
.rui-otp__live { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.rui-otp[data-state="error"] .rui-otp__box { background: var(--otp-error-fill); color: var(--otp-error); box-shadow: 0 0 0 .5px var(--otp-line); }
.rui-otp--classic[data-state="error"] .rui-otp__box { background: var(--otp-filled); color: var(--otp-ink); box-shadow: inset 0 0 0 1px rgb(229 72 77 / .6); }
:where(.dark, [data-theme="dark"]) .rui-otp--classic[data-state="error"] .rui-otp__box, .rui-otp--classic[data-theme="dark"][data-state="error"] .rui-otp__box { box-shadow: inset 0 0 0 1px rgb(255 99 105 / .55); }
.rui-otp[data-state="verifying"] .rui-otp__box::after { content: ''; position: absolute; inset: 0; background: linear-gradient(105deg, transparent 25%, rgb(255 255 255 / .5) 50%, transparent 75%); transform: translateX(-150%); animation: rui-otp-shimmer 1.25s ease-in-out infinite; }
.rui-otp[data-state="verifying"] .rui-otp__box::after { animation-delay: var(--otp-shimmer-delay, 0s); }
.rui-otp[data-state="success"] .rui-otp__separator { opacity: 0; }
.rui-otp[data-state="success"] .rui-otp__pill { background: var(--otp-success-fill); }
.rui-otp[data-state="success"] .rui-otp__resend { opacity: 0; pointer-events: none; visibility: hidden; transition: opacity .22s, visibility 0s .22s; }
@keyframes rui-otp-blink { 0%, 100% { opacity: 0; } 50% { opacity: 1; } }
@keyframes rui-otp-enter { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: translateY(0); } }
@keyframes rui-otp-shimmer { to { transform: translateX(150%); } }
.rui-otp[data-reduced-motion] *, .rui-otp[data-reduced-motion] *::after { animation: none !important; transition: none !important; }
@media (prefers-reduced-motion: reduce) {
  .rui-otp *, .rui-otp *::after { animation: none !important; transition: none !important; }
}

.rui-otp--classic .rui-otp__pill { background: var(--otp-filled); box-shadow: inset 0 0 0 1px var(--otp-filled-line); transition: height .3s cubic-bezier(.22,1,.36,1), border-radius .3s cubic-bezier(.22,1,.36,1); }
.rui-otp--classic[data-state="success"] .rui-otp__pill { background: var(--otp-filled); height: 36px; border-radius: 999px; transition-delay: .24s; }
.rui-otp__check { stroke-width: 2; }
.rui-otp--classic .rui-otp__check { stroke-width: 2.4; }
.rui-otp__message-text svg { stroke-width: 1.7; }
.rui-otp--classic .rui-otp__message-text svg { stroke-width: 2; }
